<?php require 'inc/bootstrap.php'; if (me() && me()['role']==='vendor') redirect('supply.php'); need('viewer'); $title='Dashboard';
$n = fn($sql)=>(int)q($sql)->fetchColumn();
$stats = ['Items'=>$n("SELECT COUNT(*) FROM items WHERE archived_at IS NULL AND ".scope_sql('items')." AND status<>'retired'"),'Consumables'=>$n("SELECT COUNT(*) FROM items WHERE archived_at IS NULL AND ".scope_sql('items')." AND type='consumable' AND status<>'retired'"),'Assets'=>$n("SELECT COUNT(*) FROM items WHERE archived_at IS NULL AND ".scope_sql('items')." AND type='asset' AND status<>'retired'"),'Checked out'=>$n("SELECT COUNT(*) FROM checkouts c JOIN items i ON i.id=c.item_id WHERE c.in_at IS NULL AND ".scope_sql('i')."")];
$low = q("SELECT * FROM items WHERE archived_at IS NULL AND ".scope_sql('items')." AND type='consumable' AND status<>'retired' AND min_qty>0 AND qty<=min_qty ORDER BY qty-min_qty LIMIT 6")->fetchAll();
$allOut = field_rows(); $out = array_slice($allOut, 0, 8); $nOut = count($allOut);
$nRet = $n("SELECT COUNT(*) FROM items WHERE archived_at IS NULL AND ".scope_sql('items')." AND type='returnable' AND status<>'retired'");
$upRes = array_slice(res_list(['status'=>'open']), 0, 5); $mnt = array_slice(maint_attention(), 0, 5); $nMnt = count(maint_attention());
$recent = q("SELECT t.*,i.name,u.name uname FROM transactions t JOIN items i ON i.id=t.item_id LEFT JOIN users u ON u.id=t.user_id WHERE ".scope_sql('i')." ORDER BY t.id DESC LIMIT 10")->fetchAll();
include 'inc/header.php'; $ac = attention_count();
$sections = (count($low) ? 1 : 0) + (count($out) ? 1 : 0) + (count($upRes) ? 1 : 0) + (count($mnt) ? 1 : 0); $col = $sections >= 2 ? 'col-lg-6' : 'col-12'; ?>
<?php if(!function_exists('passkeys_ok')) require_once 'inc/webauthn.php'; if(passkeys_ok() && !q("SELECT 1 FROM passkeys WHERE user_id=? LIMIT 1",[me()['id']])->fetchColumn()): ?><div class="alert alert-info d-none align-items-center gap-2 py-2 small" id="pkNudge"><i class="bi bi-fingerprint fs-5"></i><div class="flex-grow-1">Sign in faster with your fingerprint, face or screen lock. <a href="account.php">Add a passkey</a></div><button type="button" class="btn-close" aria-label="Dismiss" id="pkNudgeX"></button></div>
<script>(function(){var b=document.getElementById('pkNudge'),k='gp-pk-nudge';try{if(!window.PublicKeyCredential||!window.isSecureContext||localStorage.getItem(k))return;}catch(e){return;}b.classList.remove('d-none');b.classList.add('d-flex');document.getElementById('pkNudgeX').onclick=function(){b.remove();try{localStorage.setItem(k,'1');}catch(e){}};})();</script><?php endif; ?>
<div class="d-flex flex-wrap gap-3 small text-muted mb-3">
<a class="text-reset text-decoration-none" href="items.php"><strong class="text-body"><?=$stats['Items']?></strong> items</a>
<a class="text-reset text-decoration-none" href="items.php?type=consumable"><strong class="text-body"><?=$stats['Consumables']?></strong> consumables</a>
<a class="text-reset text-decoration-none" href="items.php?type=asset"><strong class="text-body"><?=$stats['Assets']?></strong> assets</a>
<?php if($nRet): ?><a class="text-reset text-decoration-none" href="items.php?type=returnable"><strong class="text-body"><?=$nRet?></strong> returnable</a><?php endif; ?>
<a class="text-reset text-decoration-none" href="field.php"><strong class="text-body"><?=$nOut?></strong> out now</a></div>
<div class="card card-body py-2 mb-3"><div class="d-flex flex-wrap align-items-center gap-2">
<button type="button" class="btn btn-primary" data-scan-go data-scan-mode="homemode"><i class="bi bi-upc-scan"></i> Scan</button>
<a class="btn btn-sm btn-outline-secondary" href="scan.php" title="Full scan page: move stock, issue and return"><i class="bi bi-three-dots"></i> More</a>
<?php if(can('items_add')): ?><div class="btn-group btn-group-sm" role="group" aria-label="Scan mode"><input type="radio" class="btn-check" name="homemode" id="hm1" value="search" checked><label class="btn btn-outline-secondary" for="hm1"><i class="bi bi-search"></i> Find item</label><input type="radio" class="btn-check" name="homemode" id="hm2" value="add"><label class="btn btn-outline-secondary" for="hm2"><i class="bi bi-plus-circle"></i> Add item</label></div>
<script>(function(){try{var m=localStorage.getItem('gp_homemode');if(m==='add')document.getElementById('hm2').checked=true;}catch(e){}document.querySelectorAll('input[name=homemode]').forEach(function(r){r.addEventListener('change',function(){try{localStorage.setItem('gp_homemode',r.value);}catch(e){}});});})();</script>
<?php else: ?><span class="small text-muted">Scan a code to find an item</span><?php endif; ?>
</div></div>
<?php if($ac): ?><div class="alert alert-danger py-2 d-flex justify-content-between align-items-center"><span><i class="bi bi-exclamation-triangle-fill"></i> <strong><?=$ac?></strong> need attention</span><a class="btn btn-sm btn-danger py-0" href="attention.php">View</a></div><?php endif; ?>
<?php if(!$sections && !$ac): ?><div class="text-muted">All stocked, nothing checked out.</div><?php endif; ?>
<div class="row g-3">
<?php if($low): ?><div class="<?=$col?>"><div class="card"><div class="card-header py-1 small fw-bold text-danger"><i class="bi bi-exclamation-triangle"></i> Low stock</div><ul class="list-group list-group-flush small">
<?php foreach($low as $i): ?><li class="list-group-item py-1 d-flex justify-content-between"><a href="item_view.php?id=<?=$i['id']?>"><?=h($i['name'])?></a><span class="text-muted"><?=h($i['qty']+0)?> / <?=h($i['min_qty']+0)?> <?=h($i['unit'])?></span></li><?php endforeach; ?></ul></div></div><?php endif; ?>
<?php if($out): ?><div class="<?=$col?>"><div class="card"><div class="card-header py-1 small fw-bold"><i class="bi bi-box-arrow-up-right"></i> Out now</div><ul class="list-group list-group-flush small">
<?php foreach($out as $c): $od = $c['due'] && $c['due']<date('Y-m-d'); ?><li class="list-group-item py-1 d-flex justify-content-between"><span><a href="item_view.php?id=<?=$c['item_id']?>"><?=h($c['item'])?></a><?=$c['kind']==='line'?' <strong>&times; '.h(fmt_q($c['qty'])).'</strong>':''?> <span class="text-muted">&rarr; <?=h($c['holder'])?></span></span><?php if($od): ?><span class="text-danger fw-bold">overdue</span><?php elseif($c['due']): ?><span class="text-muted"><?=h($c['due'])?></span><?php endif; ?></li><?php endforeach; ?></ul><?php if($nOut>count($out)): ?><div class="card-footer py-1 small"><a href="field.php">See all <?=$nOut?></a></div><?php endif; ?></div></div><?php endif; ?>
<?php if($upRes): ?><div class="<?=$col?>"><div class="card"><div class="card-header py-1 small fw-bold"><i class="bi bi-calendar-event"></i> Upcoming reservations</div><ul class="list-group list-group-flush small">
<?php foreach($upRes as $r): ?><li class="list-group-item py-1 d-flex justify-content-between"><span><a href="item_view.php?id=<?=$r['item_id']?>"><?=h($r['item'])?></a><?=$r['itype']==='returnable'?' <strong>&times; '.h(fmt_q($r['qty'])).'</strong>':''?> <span class="text-muted">&rarr; <?=h($r['borrower'])?></span></span><span class="text-muted text-nowrap"><?=h(res_range($r))?></span></li><?php endforeach; ?></ul><?php if(can('checkout')): ?><div class="card-footer py-1 small"><a href="reservations.php">All reservations</a></div><?php endif; ?></div></div><?php endif; ?>
<?php if($mnt): ?><div class="<?=$col?>"><div class="card"><div class="card-header py-1 small fw-bold text-danger"><i class="bi bi-wrench-adjustable"></i> Maintenance due</div><ul class="list-group list-group-flush small">
<?php foreach($mnt as $t): [$st,,$badge]=maint_state($t); ?><li class="list-group-item py-1 d-flex justify-content-between"><span><a href="item_view.php?id=<?=$t['item_id']?>"><?=h($t['item'])?></a> <span class="text-muted"><?=h($t['title'])?></span></span><?=$badge?></li><?php endforeach; ?></ul><?php if($nMnt>count($mnt)): ?><div class="card-footer py-1 small"><a href="maintenance.php?view=due">See all <?=$nMnt?></a></div><?php endif; ?></div></div><?php endif; ?>
</div>
<?php if($recent): ?><details class="mt-3"><summary class="small text-muted" style="cursor:pointer">Recent activity (<?=count($recent)?>)</summary><div class="card mt-2"><table class="table table-sm small mb-0"><tbody>
<?php foreach($recent as $t): ?><tr><td class="text-muted"><?=h(substr($t['created_at'],5,11))?></td><td><a href="item_view.php?id=<?=$t['item_id']?>"><?=h($t['name'])?></a></td><td><?=h($t['type'])?> <?=$t['qty']!=0?h($t['qty']+0):''?></td><td><?=h($t['uname'])?></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?>
<?php include 'inc/footer.php'; ?>
